"""Vetted remediation templates (R2, R12). HardenGarden displays them; it never runs them."""

from __future__ import annotations

from importlib import resources

from hardengarden import __version__
from hardengarden.core.models import CheckMeta

HEADER = """\
# ---------------------------------------------------------------------------
# HardenGarden remediation for {id}: {title}
# Generated by HardenGarden {version}. REVIEW BEFORE RUNNING.
#
# Dry run by default: this prints what it would change and changes nothing.
# To apply:  sudo HG_APPLY=1 bash {script}
# Files are backed up as <file>.hardengarden-bak.<timestamp> before editing.
# ---------------------------------------------------------------------------
"""


class TemplateNotFoundError(LookupError):
    pass


def template_source(name: str) -> str:
    if "/" in name or not name.endswith(".sh"):
        msg = f"invalid template name: {name!r}"
        raise TemplateNotFoundError(msg)
    resource = resources.files("hardengarden.remediation").joinpath("templates", name)
    if not resource.is_file():
        msg = f"no remediation template named {name!r}"
        raise TemplateNotFoundError(msg)
    return resource.read_text(encoding="utf-8")


def render(meta: CheckMeta) -> str | None:
    """Return the full script text for a check, or ``None`` if it has no template."""
    if meta.remediation_template is None:
        return None
    source = template_source(meta.remediation_template)
    shebang, _, body = source.partition("\n")
    header = HEADER.format(
        id=meta.id, title=meta.title, version=__version__, script=meta.remediation_template
    )
    return f"{shebang}\n{header}{body}"
